  })

  it('handles a leap-day start', () => {
    const s = rent(generateSchedule({ startDate: '2028-02-29', endDate: '2029-03-28', monthlyRentSen: 1000, depositSen: 0 }))
    expect(s[11].dueDate).toBe('2029-01-29')
