    ['2026-13-01', '2027-01-01'],
    ['2026-1-05', '2026-03-01'],
    [' 2026-01-05', '2026-03-01'],
    ['2026-01-05T00:00:00Z', '2026-03-01'],
    ['2025-02-29', '2025-03-01'],
    ['2026-01-01', '2026-00-10'],
