export function senToNumber(sen: bigint): number {
  if (sen > BigInt(Number.MAX_SAFE_INTEGER) || sen < -BigInt(Number.MAX_SAFE_INTEGER)) {
    throw new Error('Amount out of range')
  }
  return Number(sen)
}

