  const seen = new Set<unknown>()
  const visit = (value: unknown, depth: number): string | undefined => {
    if (!value || typeof value !== 'object' || seen.has(value) || depth > 6) return undefined
    seen.add(value)
    const record = value as Record<string, unknown>
    for (const key of ['originalCode', 'code']) {
      const code = record[key]
      if (typeof code !== 'string') continue
      if (code === 'P2002') return '23505'
      if (/^[0-9A-Z]{5}$/.test(code) && !/^P[1-6]\d{3}$/.test(code)) return code
    }
    for (const key of ['cause', 'meta', 'driverAdapterError']) {
      const found = visit(record[key], depth + 1)
      if (found) return found
    }
    return undefined
  }
  return visit(error, 0)
}

// Who is calling, and what they may see. Roles come only from our tables (memberships for staff and
// managers, tenants.user_id for tenants), never from anything the user can edit such as user_metadata.
import { prisma } from '../prisma'
import { forbidden, notFound, UUID_RE } from './http'

export type StaffRole = 'manager' | 'staff'
export type Role = StaffRole | 'tenant'

export type Caller =
  | { userId: string; role: StaffRole; orgId: string; tenantId: null }
  | { userId: string; role: 'tenant'; orgId: string; tenantId: string }

export async function loadCaller(userId: string): Promise<Caller | null> {
  const membership = await prisma.memberships.findUnique({ where: { user_id: userId } })
  if (membership && (membership.role === 'manager' || membership.role === 'staff')) {
    return { userId, role: membership.role, orgId: membership.org_id, tenantId: null }
  }
  const tenant = await prisma.tenants.findUnique({ where: { user_id: userId } })
  if (tenant) return { userId, role: 'tenant', orgId: tenant.org_id, tenantId: tenant.id }
  return null
}

// 403: the caller can see the record but their role does not allow the action.
export function requireRole(caller: Caller, ...roles: Role[]): void {
  if (!roles.includes(caller.role)) throw forbidden()
}

// Staff and managers see their organization's leases; a tenant sees only their own.
export function canSeeLease(caller: Caller, lease: { org_id: string; tenant_id: string }): boolean {
  return caller.role === 'tenant' ? lease.tenant_id === caller.tenantId : lease.org_id === caller.orgId
}

// 404 for anything outside the caller's scope, so other organizations' records are never revealed.
export async function findLeaseForCaller(caller: Caller, leaseId: string) {
  if (!UUID_RE.test(leaseId)) throw notFound('Lease not found')
  const lease = await prisma.leases.findUnique({ where: { id: leaseId } })
  if (!lease || !canSeeLease(caller, lease)) throw notFound('Lease not found')
  return lease
}

export async function findPaymentForCaller(caller: Caller, paymentId: string) {
  if (!UUID_RE.test(paymentId)) throw notFound('Payment not found')
  const payment = await prisma.payments.findUnique({
    where: { id: paymentId },
    include: { leases: { select: { org_id: true, tenant_id: true } } },
  })
  if (!payment || !canSeeLease(caller, payment.leases)) throw notFound('Payment not found')
  return payment
}

// Shared transaction helpers for everything that moves money.
import { planAllocation, compareAllocationOrder, type InvoiceBalance } from '../allocation'
import type { Prisma } from '../generated/prisma/client'
import { prisma } from '../prisma'
import { dateOnly } from '../time'

export type Tx = Prisma.TransactionClient
type Db = Tx | typeof prisma

// Concurrent requests on one lease queue on the lease lock, so give them time instead of failing.
export const TX_OPTIONS = { maxWait: 10_000, timeout: 20_000 }

// Every money-changing operation on a lease takes this row lock first (record, approve, reject, void,
// bill creation, webhook settlement). Requests on the same lease therefore run one after another, and
// each re-reads balances and statuses after the previous one has committed. Lock order is always
// lease first, then its payments/bills, so these transactions cannot deadlock each other.
export async function lockLease(tx: Tx, leaseId: string): Promise<void> {
  await tx.$queryRaw`SELECT id FROM public.leases WHERE id = ${leaseId}::uuid FOR UPDATE`
}

export interface LeaseInvoice extends InvoiceBalance {
  periodStart: string | null
  periodEnd: string | null
}

// The lease's invoices with their paid amounts (sum of allocations), in allocation order.
export async function loadInvoiceBalances(db: Db, leaseId: string): Promise<LeaseInvoice[]> {
  const rows = await db.invoices.findMany({
    where: { lease_id: leaseId },
    include: { payment_allocations: { select: { amount_sen: true } } },
  })
  return rows
    .map((i) => ({
      id: i.id,
      kind: i.kind === 'deposit' ? ('deposit' as const) : ('rent' as const),
      periodIndex: i.period_index,
      periodStart: i.period_start ? dateOnly(i.period_start) : null,
      periodEnd: i.period_end ? dateOnly(i.period_end) : null,
      dueDate: dateOnly(i.due_date),
      amountSen: i.amount_sen,
      paidSen: i.payment_allocations.reduce((sum, a) => sum + a.amount_sen, 0n),
    }))
    .sort(compareAllocationOrder)
}

export async function pendingTotal(tx: Tx, leaseId: string): Promise<bigint> {
  const result = await tx.payments.aggregate({
    where: { lease_id: leaseId, status: 'pending_verification' },
    _sum: { amount_sen: true },
  })
  return result._sum.amount_sen ?? 0n
}

// Allocates an approved payment and stores what is left as unapplied_sen. Caller holds the lease lock.
export async function allocatePayment(
  tx: Tx,
  payment: { id: string; org_id: string; amount_sen: bigint },
  invoices: InvoiceBalance[],
) {
  const plan = planAllocation(invoices, payment.amount_sen)
  if (plan.allocations.length > 0) {
    await tx.payment_allocations.createMany({
      data: plan.allocations.map((a) => ({
        org_id: payment.org_id,
        payment_id: payment.id,
        invoice_id: a.invoiceId,
        amount_sen: a.amountSen,
      })),
    })
  }
  await tx.payments.update({ where: { id: payment.id }, data: { unapplied_sen: plan.unappliedSen } })
  return plan
}

export async function writeAudit(
  tx: Tx,
  entry: { orgId: string; actorId: string | null; action: string; entityId: string; details: Prisma.InputJsonObject },
): Promise<void> {
  await tx.audit_log.create({
    data: {
      org_id: entry.orgId,
      actor_id: entry.actorId,
      action: entry.action,
      entity_id: entry.entityId,
      details: entry.details,
    },
  })
}

