import 'server-only'
import { createClient } from '@supabase/supabase-js'

// Secret-key client: bypasses RLS and Storage policies. Server only (the import above makes a client
// bundle that imports this fail to build). Used for Storage housekeeping and signed URLs, after our own checks.
export function adminClient() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL
  const key = process.env.SUPABASE_SECRET_KEY
  if (!url || !key) throw new Error('Supabase server environment is not configured')
  return createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } })
}

import { createServerClient } from '@supabase/ssr'
import { cookies } from 'next/headers'

// Per-request client that reads the session from cookies (publishable key, so RLS applies).
export async function createClient() {
  const cookieStore = await cookies()
  return createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!, {
    cookies: {
      getAll() {
        return cookieStore.getAll()
      },
      setAll(cookiesToSet) {
        try {
          cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options))
        } catch {
          // Called from a Server Component, where cookies are read-only; proxy.ts refreshes the session.
        }
      },
    },
  })
}

import { createBrowserClient } from '@supabase/ssr'

// Browser client with the publishable key: everything it does goes through RLS and Storage policies.
export function createClient() {
  return createBrowserClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!)
}

import 'server-only'
import { createClient as createTokenClient } from '@supabase/supabase-js'
import { createClient as createCookieClient } from '../supabase/server'
import { loadCaller, type Caller } from './caller'
import { forbidden, unauthorized } from './http'

// Authenticates the request: `Authorization: Bearer <access token>` (API clients and tests) or the session
// cookie (the web app). Both are checked with the Auth server through getUser(), never getSession().
export async function authenticatedUserId(req?: Request): Promise<string | null> {
  const header = req?.headers.get('authorization')
  if (header) {
    const match = /^Bearer\s+(\S+)$/i.exec(header)
    if (!match) return null
    const client = createTokenClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY!, {
      auth: { persistSession: false, autoRefreshToken: false },
    })
    const { data, error } = await client.auth.getUser(match[1])
    return error || !data.user ? null : data.user.id
  }
  const supabase = await createCookieClient()
  const { data, error } = await supabase.auth.getUser()
  return error || !data.user ? null : data.user.id
}

// 401 without a valid login; 403 for a valid login that has no role in any organization.
export async function getCaller(req?: Request): Promise<Caller> {
  const userId = await authenticatedUserId(req)
  if (!userId) throw unauthorized()
  const caller = await loadCaller(userId)
  if (!caller) throw forbidden('This account has no access')
  return caller
}

// For server components: null instead of throwing, so the page can redirect to /login.
export async function getPageCaller(): Promise<Caller | null> {
  const userId = await authenticatedUserId()
  return userId ? loadCaller(userId) : null
}

// Bank transfer slips in the private payment-slips bucket, at <org_id>/<file>.
import { prisma } from '../prisma'
import { adminClient } from '../supabase/admin'

export const SLIP_BUCKET = 'payment-slips'

export function isSlipPathInOrg(orgId: string, path: string): boolean {
  return path.startsWith(`${orgId}/`) && /^[^/]+\/[^/]+$/.test(path) && !path.includes('..')
}

export async function slipExists(path: string): Promise<boolean> {
  const rows = await prisma.$queryRaw<{ n: bigint }[]>`
    SELECT count(*)::bigint AS n FROM storage.objects WHERE bucket_id = ${SLIP_BUCKET} AND name = ${path}`
  return (rows[0]?.n ?? 0n) > 0n
}

// Called when recording a payment fails after the slip was uploaded. Deletes the file only if it is in the
// caller's own organization folder and no payment uses it, so a bad request cannot remove someone else's slip.
export async function discardOrphanSlip(orgId: string, path: string): Promise<void> {
  try {
    if (!isSlipPathInOrg(orgId, path)) return
    if ((await prisma.payments.count({ where: { slip_path: path } })) > 0) return
    const { error } = await adminClient().storage.from(SLIP_BUCKET).remove([path])
    if (error) console.error('Could not delete orphaned slip:', error.message)
  } catch (error) {
    console.error('Could not delete orphaned slip:', error instanceof Error ? error.message : 'unknown error')
  }
}

// Short-lived link, created only after the caller's access to the payment has been checked.
export async function signedSlipUrl(path: string): Promise<string> {
  const { data, error } = await adminClient().storage.from(SLIP_BUCKET).createSignedUrl(path, 60)
  if (error || !data) throw new Error('Could not sign slip URL')
  return data.signedUrl
}

import { z } from 'zod'
