  unitId: z.string().regex(UUID_RE, 'must be a uuid'),
  tenantId: z.string().regex(UUID_RE, 'must be a uuid'),
  startDate: z.string(),
  endDate: z.string(),
  monthlyRentSen: z.number(),
  depositSen: z.number(),
