import { z } from 'zod'
import { remainingBalance } from '../allocation'
import { prisma } from '../prisma'
import { parseInstant, toMytIso } from '../time'
import { findLeaseForCaller, findPaymentForCaller, requireRole, type Caller } from './caller'
import { allocatePayment, loadInvoiceBalances, lockLease, pendingTotal, TX_OPTIONS, writeAudit } from './db'
import { badRequest, HttpError, parseBody } from './http'
import { discardOrphanSlip, isSlipPathInOrg, slipExists } from './slips'

const recordSchema = z.object({
  amountSen: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
  method: z.enum(['cash', 'bank_transfer']),
  receivedAt: z.string(),
  slipPath: z.string().optional(),
})

const reasonSchema = z.object({
  reason: z.string().trim().min(5, 'must be at least 5 characters'),
})

// POST /api/leases/:leaseId/payments. If anything fails after the slip was uploaded, the slip is removed.
export async function recordPayment(caller: Caller, leaseId: string, input: unknown): Promise<{ id: string; status: string }> {
  try {
    return await recordPaymentChecked(caller, leaseId, input)
  } catch (error) {
    const slipPath = (input as { slipPath?: unknown } | null)?.slipPath
    if (typeof slipPath === 'string' && caller.role !== 'tenant') await discardOrphanSlip(caller.orgId, slipPath)
    throw error
  }
}

async function recordPaymentChecked(caller: Caller, leaseId: string, input: unknown) {
  const lease = await findLeaseForCaller(caller, leaseId)
  requireRole(caller, 'manager', 'staff')
  const body = parseBody(recordSchema, input)
  const receivedAt = parseInstant(body.receivedAt)
  if (!receivedAt) throw badRequest('receivedAt must be an ISO 8601 date-time with an offset, e.g. 2026-03-01T00:30:00+08:00')

  let slipPath: string | null = null
  if (body.method === 'bank_transfer') {
    if (!body.slipPath) throw badRequest('A bank transfer needs a slip')
    if (!isSlipPathInOrg(lease.org_id, body.slipPath) || !(await slipExists(body.slipPath))) {
      throw badRequest("slipPath must point to an uploaded file in the organization's folder")
    }
    slipPath = body.slipPath
  } else if (body.slipPath !== undefined) {
    throw badRequest('Only bank transfers take a slip')
  }

  const amount = BigInt(body.amountSen)
  const approved = caller.role === 'manager' // manager payments are approved immediately; staff payments wait

  return prisma.$transaction(async (tx) => {
    await lockLease(tx, lease.id)
    const invoices = await loadInvoiceBalances(tx, lease.id)
    // Cap: remaining balance minus everything still pending, read under the lease lock.
    const cap = remainingBalance(invoices) - (await pendingTotal(tx, lease.id))
    if (amount > cap) {
      throw new HttpError(422, `Amount is more than the lease's remaining balance (at most ${cap > 0n ? cap : 0n} sen)`)
    }
    const payment = await tx.payments.create({
      data: {
        org_id: lease.org_id,
        lease_id: lease.id,
        amount_sen: amount,
        method: body.method,
        status: approved ? 'approved' : 'pending_verification',
        received_at: receivedAt,
        slip_path: slipPath,
        recorded_by: caller.userId,
        decided_by: approved ? caller.userId : null,
        decided_at: approved ? new Date() : null,
      },
    })
    const details = { amountSen: body.amountSen, method: body.method, receivedAt: toMytIso(receivedAt) }
    await writeAudit(tx, { orgId: lease.org_id, actorId: caller.userId, action: 'payment.recorded', entityId: payment.id, details })
    if (approved) {
      const plan = await allocatePayment(tx, payment, invoices)
      await writeAudit(tx, {
        orgId: lease.org_id,
        actorId: caller.userId,
        action: 'payment.approved',
        entityId: payment.id,
        details: { ...details, recordedByManager: true, allocatedTo: plan.allocations.map((a) => a.invoiceId) },
      })
    }
    return { id: payment.id, status: payment.status }
  }, TX_OPTIONS)
}

// POST /api/payments/:paymentId/approve
export async function approvePayment(caller: Caller, paymentId: string): Promise<{ status: string }> {
  const found = await findPaymentForCaller(caller, paymentId)
  requireRole(caller, 'manager')
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, found.lease_id)
    // Re-read under the lock: a concurrent approval may have committed while we waited.
    const payment = await tx.payments.findUniqueOrThrow({ where: { id: found.id } })
    if (payment.status !== 'pending_verification') throw new HttpError(409, 'Payment is not pending verification')
    const invoices = await loadInvoiceBalances(tx, payment.lease_id)
    const remaining = remainingBalance(invoices)
    if (payment.amount_sen > remaining) {
      throw new HttpError(422, `Payment is more than the lease's remaining balance (${remaining} sen); it stays pending`)
    }
    await tx.payments.update({
      where: { id: payment.id },
      data: { status: 'approved', decided_by: caller.userId, decided_at: new Date() },
    })
    const plan = await allocatePayment(tx, payment, invoices)
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: caller.userId,
      action: 'payment.approved',
      entityId: payment.id,
      details: { amountSen: Number(payment.amount_sen), allocatedTo: plan.allocations.map((a) => a.invoiceId) },
    })
    return { status: 'approved' }
  }, TX_OPTIONS)
}

// POST /api/payments/:paymentId/reject
export async function rejectPayment(caller: Caller, paymentId: string, input: unknown): Promise<{ status: string }> {
  const found = await findPaymentForCaller(caller, paymentId)
  requireRole(caller, 'manager')
  const { reason } = parseBody(reasonSchema, input)
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, found.lease_id)
    const payment = await tx.payments.findUniqueOrThrow({ where: { id: found.id } })
    if (payment.status !== 'pending_verification') throw new HttpError(409, 'Payment is not pending verification')
    await tx.payments.update({
      where: { id: payment.id },
      data: { status: 'rejected', decided_by: caller.userId, decided_at: new Date(), decision_reason: reason },
    })
    await writeAudit(tx, { orgId: payment.org_id, actorId: caller.userId, action: 'payment.rejected', entityId: payment.id, details: { reason } })
    return { status: 'rejected' }
  }, TX_OPTIONS)
}

// POST /api/payments/:paymentId/void. Removes only this payment's allocations; other payments (including any
// unapplied online credit) are left exactly as they are. See DECISIONS.md, question 5.
export async function voidPayment(caller: Caller, paymentId: string, input: unknown): Promise<{ status: string }> {
  const found = await findPaymentForCaller(caller, paymentId)
  requireRole(caller, 'manager')
  const { reason } = parseBody(reasonSchema, input)
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, found.lease_id)
    const payment = await tx.payments.findUniqueOrThrow({ where: { id: found.id } })
    if (payment.status !== 'approved') throw new HttpError(409, 'Only approved payments can be voided')
    const removed = await tx.payment_allocations.findMany({ where: { payment_id: payment.id } })
    await tx.payment_allocations.deleteMany({ where: { payment_id: payment.id } })
    await tx.payments.update({
      where: { id: payment.id },
      data: { status: 'voided', decided_by: caller.userId, decided_at: new Date(), decision_reason: reason },
    })
    await writeAudit(tx, {
      orgId: payment.org_id,
      actorId: caller.userId,
      action: 'payment.voided',
      entityId: payment.id,
      details: { reason, removedAllocations: removed.map((a) => ({ invoiceId: a.invoice_id, amountSen: Number(a.amount_sen) })) },
    })
    return { status: 'voided' }
  }, TX_OPTIONS)
}

// Online payments: bill creation (tenant) and the gateway webhook (the only thing that can settle a bill).
import { createHmac, randomBytes, timingSafeEqual } from 'node:crypto'
import { amountDueNow } from '../allocation'
import { malaysiaDate } from '../billing'
import { senToNumber } from '../money'
import { prisma } from '../prisma'
import { parseGatewayTime } from '../time'
import { findLeaseForCaller, type Caller } from './caller'
import { allocatePayment, loadInvoiceBalances, lockLease, TX_OPTIONS, writeAudit } from './db'
import { dbErrorCode, forbidden, HttpError } from './http'

const BILL_ID_RE = /^bill_[0-9a-f]{32}$/

// POST /api/leases/:leaseId/gateway-bills. Only the lease's own tenant may create a bill.
export async function createGatewayBill(caller: Caller, leaseId: string, now = new Date()): Promise<{ billId: string; amountSen: number }> {
  const lease = await findLeaseForCaller(caller, leaseId)
  if (caller.role !== 'tenant') throw forbidden('Only the tenant can pay online')
  return prisma.$transaction(async (tx) => {
    await lockLease(tx, lease.id)
    const due = amountDueNow(await loadInvoiceBalances(tx, lease.id), malaysiaDate(now))
    if (due <= 0n) throw new HttpError(422, 'Nothing is due on this lease')
    // 128 random bits: bill ids cannot be guessed.
    const bill = await tx.gateway_bills.create({
      data: { id: `bill_${randomBytes(16).toString('hex')}`, org_id: lease.org_id, lease_id: lease.id, amount_sen: due, created_by: caller.userId },
    })
    return { billId: bill.id, amountSen: senToNumber(bill.amount_sen) }
  }, TX_OPTIONS)
}

// Every field except x_signature, sorted by key (character code order), as key+value, joined with '|'.
export function signatureSource(fields: [string, string][]): string {
  return fields
    .filter(([key]) => key !== 'x_signature')
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([key, value]) => `${key}${value}`)
    .join('|')
}

export function computeSignature(fields: [string, string][], key: string): string {
  return createHmac('sha256', key).update(signatureSource(fields)).digest('hex')
}

function signatureIsValid(fields: [string, string][], provided: string | undefined, key: string): boolean {
  if (!provided || !/^[0-9a-f]{64}$/i.test(provided)) return false
  return timingSafeEqual(Buffer.from(computeSignature(fields, key), 'hex'), Buffer.from(provided, 'hex'))
}

type WebhookResult = { status: number; body: Record<string, unknown> }

// POST /api/webhooks/gateway. Never logs the key or the payload.
export async function handleGatewayCallback(rawBody: string): Promise<WebhookResult> {
  const key = process.env.GATEWAY_X_SIGNATURE_KEY
  if (!key) throw new Error('GATEWAY_X_SIGNATURE_KEY is not configured')

  const fields = [...new URLSearchParams(rawBody).entries()]
  const byKey = new Map(fields)
  if (byKey.size !== fields.length) return { status: 400, body: { error: 'Duplicate field' } }
  if (!signatureIsValid(fields, byKey.get('x_signature'), key)) return { status: 401, body: { error: 'Invalid signature' } }

  const billId = byKey.get('id') ?? ''
  const bill = BILL_ID_RE.test(billId) ? await prisma.gateway_bills.findUnique({ where: { id: billId } }) : null
  if (!bill) return { status: 404, body: { error: 'Unknown bill' } }

  const paid = byKey.get('paid')
  if (paid !== 'true' && paid !== 'false') return { status: 400, body: { error: 'paid must be true or false' } }

  if (paid === 'false') {
    await prisma.$transaction(async (tx) => {
      await lockLease(tx, bill.lease_id)
      // Only a pending bill can fail: a failed bill stays failed and a paid bill never goes back.
      await tx.gateway_bills.updateMany({ where: { id: bill.id, status: 'pending' }, data: { status: 'failed', updated_at: new Date() } })
    }, TX_OPTIONS)
    return { status: 200, body: { ok: true } }
  }

  const paidAmount = byKey.get('paid_amount') ?? ''
  if (!/^\d+$/.test(paidAmount) || BigInt(paidAmount) !== bill.amount_sen) {
    return { status: 422, body: { error: 'paid_amount does not match the bill' } }
  }
  const paidAt = parseGatewayTime(byKey.get('paid_at'))
  if (!paidAt) return { status: 400, body: { error: 'Invalid paid_at' } }

  try {
    await prisma.$transaction(async (tx) => {
      // Duplicate deliveries queue on this lock; the second one then sees status 'paid' and does nothing.
      await lockLease(tx, bill.lease_id)
      const current = await tx.gateway_bills.findUniqueOrThrow({ where: { id: bill.id } })
      if (current.status === 'paid') return
      await tx.gateway_bills.update({
        where: { id: bill.id },
        data: { status: 'paid', paid_at: paidAt, transaction_id: byKey.get('transaction_id') ?? null, updated_at: new Date() },
      })
      // payments.gateway_bill_id is UNIQUE: even if the lock were bypassed, a second payment cannot be inserted.
      const payment = await tx.payments.create({
        data: {
          org_id: bill.org_id,
          lease_id: bill.lease_id,
          amount_sen: bill.amount_sen,
          method: 'online',
          status: 'approved',
          received_at: paidAt,
          gateway_bill_id: bill.id,
          decided_at: new Date(),
        },
      })
      const plan = await allocatePayment(tx, payment, await loadInvoiceBalances(tx, bill.lease_id))
      await writeAudit(tx, {
        orgId: bill.org_id,
        actorId: null,
        action: 'payment.online_settled',
        entityId: payment.id,
        details: { billId: bill.id, amountSen: Number(bill.amount_sen), unappliedSen: Number(plan.unappliedSen) },
      })
    }, TX_OPTIONS)
  } catch (error) {
    if (dbErrorCode(error) === '23505') return { status: 200, body: { ok: true } } // repeat delivery
    throw error
  }
  return { status: 200, body: { ok: true } }
}

import { invoiceStatus, malaysiaDate } from '../billing'
import { senToNumber } from '../money'
import { prisma } from '../prisma'
import { monthRange, mytMonthStart, shiftMonth } from '../time'
import { requireRole, type Caller } from './caller'
import { badRequest } from './http'

// GET /api/reports/collections. Approved payments per Malaysia calendar month of received_at,
// one entry per month in order, including months with nothing collected.
export async function collectionsReport(caller: Caller, from: unknown, to: unknown) {
  requireRole(caller, 'manager', 'staff')
  const months = monthRange(from, to)
  if (!months) throw badRequest('from and to must be YYYY-MM, from <= to, at most 120 months')
  const start = mytMonthStart(months[0]).toISOString()
  const end = mytMonthStart(shiftMonth(months[months.length - 1], 1)).toISOString()
  const rows = await prisma.$queryRaw<{ month: string; total: bigint }[]>`
    SELECT to_char(received_at AT TIME ZONE 'Asia/Kuala_Lumpur', 'YYYY-MM') AS month, SUM(amount_sen)::bigint AS total
    FROM public.payments
    WHERE org_id = ${caller.orgId}::uuid AND status = 'approved'
      AND received_at >= ${start}::timestamptz AND received_at < ${end}::timestamptz
    GROUP BY 1`
  const totals = new Map(rows.map((r) => [r.month, r.total]))
  return months.map((month) => ({ month, collectedSen: senToNumber(totals.get(month) ?? 0n) }))
}

export async function overdueInvoiceCount(caller: Caller, now = new Date()): Promise<number> {
  requireRole(caller, 'manager', 'staff')
  const rows = await prisma.$queryRaw<{ due_date: string; amount_sen: bigint; paid_sen: bigint }[]>`
    SELECT to_char(i.due_date, 'YYYY-MM-DD') AS due_date, i.amount_sen, COALESCE(SUM(a.amount_sen), 0)::bigint AS paid_sen
    FROM public.invoices i LEFT JOIN public.payment_allocations a ON a.invoice_id = i.id
    WHERE i.org_id = ${caller.orgId}::uuid
    GROUP BY i.id`
  return rows.filter(
    (r) => invoiceStatus({ dueDate: r.due_date, amountSen: Number(r.amount_sen), paidSen: Number(r.paid_sen) }, now) === 'overdue',
  ).length
}

export async function listLeases(caller: Caller) {
  requireRole(caller, 'manager', 'staff')
  const leases = await prisma.leases.findMany({
    where: { org_id: caller.orgId },
    include: { units: { select: { name: true } }, tenants: { select: { full_name: true } } },
    orderBy: [{ units: { name: 'asc' } }, { start_date: 'asc' }],
  })
  return leases.map((l) => ({
    id: l.id,
    unitName: l.units.name,
    tenantName: l.tenants.full_name,
    startDate: l.start_date.toISOString().slice(0, 10),
    endDate: l.end_date.toISOString().slice(0, 10),
    monthlyRentSen: senToNumber(l.monthly_rent_sen),
  }))
}

export function lastMonths(count: number, now = new Date()): { from: string; to: string } {
  const to = malaysiaDate(now).slice(0, 7)
  return { from: shiftMonth(to, -(count - 1)), to }
}

