    const unit = [...ids.units].find(([, id]) => id === r.unit_id)?.[0]
    if (unit) ids.leases.set(unit, String(r.id))
  }
  ids.org = String((await rest('organizations?select=id', NW_MANAGER)).rows[0]?.id)
