input.command:
Set-Location D:\dev\ezyfusion-rent
"== status"; git status --short
"== tracked files: $((git ls-files | Measure-Object).Count)"
$files = @(git ls-files) + @('BRIEF.md', 'DECISIONS.md') | Sort-Object -Unique | Where-Object { Test-Path $_ }
$patterns = [ordered]@{
  'JWT (eyJ...)' = 'eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}';
  'sb_secret_' = 'sb_secret_[A-Za-z0-9_-]+';
  'sb_publishable_' = 'sb_publishable_[A-Za-z0-9_-]+';
  'OpenAI/Anthropic style sk-' = '\bsk-[A-Za-z0-9_-]{16,}';
  'GitHub token' = '\b(ghp|gho|ghs|github_pat)_[A-Za-z0-9_]{20,}';
  'AWS key' = '\bAKIA[0-9A-Z]{16}\b';
  'Private key block' = '-----BEGIN [A-Z ]*PRIVATE KEY-----';
  'Stripe/other live key' = '\b(sk|rk|pk)_live_[A-Za-z0-9]+';
  'postgres URL' = 'postgres(ql)?://[^\s"''`]+';
  'Windows user path' = '(?i)C:\\Users\\[^\\\s]+';
  'Personal user name' = '(?i)darkenergy|[redacted-account-email]';
}
foreach ($k in $patterns.Keys) {
  $hits = $files | Where-Object { $_ -notmatch '^package-lock\.json$' } | ForEach-Object { Select-String -Path $_ -Pattern $patterns[$k] -AllMatches } 
  $where = ($hits | ForEach-Object { "$($_.Path.Replace("$PWD\",'')):$($_.LineNumber)" } | Select-Object -Unique) -join ', '
  "{0}: {1} hit(s) {2}" -f $k, ($hits | Measure-Object).Count, $where
}
"== email addresses (excluding .test, example.com, anthropic noreply, package-lock)"
$files | Where-Object { $_ -ne 'package-lock.json' } | ForEach-Object { Select-String -Path $_ -Pattern '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}' -AllMatches } | ForEach-Object { $_.Matches.Value } | Where-Object { $_ -notmatch '\.test$|@example\.com$|^noreply@anthropic\.com$' } | Sort-Object -Unique

